import styles from "./input-error.module.less";
import { AnimatePresence, motion } from "framer-motion";
import { Icon } from "@/core/components/primitives/icon/icon";
import { useTranslation } from "react-i18next";
import { ValidationType } from "@/core/helpers/form-builder";

type InputErrorProps = {
  /** Whether the error box is shown. It animates in and out, so toggling it does not unmount abruptly. */
  showError: boolean;
  /** Marks the field as required: when neither errorText nor a validationType message applies, the generic "required" message is shown instead. */
  isRequired?: boolean;
  /** Explicit message. Takes priority over the validationType and required fallbacks. */
  errorText?: string;
  /** Validation type of the field, used to pick a sensible default message when no errorText is supplied. */
  validationType?: ValidationType;
  /** Picks the icon and colors: "error" is red, "warning" uses the warning icon color with black text. Defaults to "error". */
  errorLevel?: "warning" | "error";
  /** Id for the error element, so a control can reference it via aria-describedby. */
  id?: string;
  "data-testid"?: string;
};

export const InputError = ({
  showError,
  isRequired,
  errorText,
  validationType,
  errorLevel = "error",
  id,
  "data-testid": dataTestId,
}: InputErrorProps) => {
  const { t } = useTranslation();

  // Resolve the message to show, in priority order:
  //   1. an explicit errorText,
  //   2. a validation-type specific message (e.g. a malformed phone number, even in an optional field),
  //   3. the generic "required" message when a required field is left empty.
  // When none apply there is nothing to say, so render nothing. This keeps a field silent when its
  // parent renders its own dedicated InputError (e.g. grouped inputs, gift-card-form).
  const validationTypeMessage = () => {
    switch (validationType) {
      case "EMAIL":
        return t("inputValidationEmail");
      case "PHONE":
        return t("inputValidationPhone");
      case "ZIPCODE":
        return t("inputValidationPostalCode");
      case "BIRTHDATE":
        return t("inputValidationDateOfBirth");
      case "DATE":
        return t("inputValidationDate");
      default:
        return undefined;
    }
  };
  const errorMessage = errorText || validationTypeMessage() || (isRequired ? t("inputValidationRequired") : undefined);

  if (!errorMessage) {
    return null;
  }

  return (
    <AnimatePresence mode="wait">
      {showError && (
        <motion.div
          key="inputError"
          id={id}
          initial={{ opacity: 0, height: 0 }}
          animate={{
            opacity: 1,
            height: "auto",
          }}
          exit={{ opacity: 0, height: 0, margin: 0, transition: { opacity: { duration: 0.1 } } }}
          transition={{
            duration: 0.2,
            easings: "easeInOut",
          }}
          className={styles.innerWrapper}
          data-error-level={errorLevel}
          data-testid={dataTestId}
        >
          <div className={styles.iconWrapper}>
            <Icon name={errorLevel} size="l" className={styles.icon} />
          </div>

          <div key="errorMessage" className={styles.message}>
            <span className={`${styles.message} p_small`} data-error-level={errorLevel}>
              {errorMessage}
            </span>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};
