import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, waitFor, within } from "storybook/test";
import { CalendarDateField, CalendarDatesProps } from "./calendar-date-field";
import {
  ShowcaseLayout,
  Variant,
  WithMockedDate,
  argTypesMockDate,
  showcaseParameters,
  withMockedDate,
} from "@/storybook/preview";

// Local time on purpose: the component builds its days from YYYY-MM-DD strings at local midnight,
// so "today" must be a local date as well for the past-day filtering to line up.
const MOCKED_NOW = new Date("2023-05-01T10:00:00");

const calendarDates = {
  startDate: "2023-04-25",
  endDate: "2023-05-21",
  selectedDates: [{ date: "2023-05-26", fullDate: "2023-05-26" }],
} satisfies CalendarDatesProps;

const fullyBookedDates = {
  startDate: "2023-05-03",
  endDate: "2023-05-06",
  selectedDates: [{ date: "2023-05-16", fullDate: "2023-05-16" }],
} satisfies CalendarDatesProps;

const meta = {
  title: "Primitives/Form Fields/Calendar Date Field",
  component: CalendarDateField,
  decorators: [withMockedDate],
  parameters: {
    docs: {
      description: {
        component:
          "Single-date picker for form fields, built on the `Calendar` primitive. `calendarDates` spans " +
          "`startDate` to `endDate` (YYYY-MM-DD, every day in between is selectable) and `selectedDates` adds " +
          "extra selectable days by `fullDate`; all other days in the shown months are disabled. " +
          "`fullyBookedDates` has the same shape and disables those days with a fully-booked marker. With " +
          "`removeDaysInThePast` (default true) days before today are " +
          "dropped and the calendar opens on the first remaining day. The chosen day is kept in internal " +
          "state (there is no value prop), and `onChangeDate` only fires for selectable days.",
      },
    },
  },
  argTypes: {
    ...argTypesMockDate,
    onChangeDate: { table: { disable: true } },
  },
  args: {
    mockedDate: MOCKED_NOW,
    calendarDates,
    onChangeDate: fn(),
    removeDaysInThePast: true,
  },
} satisfies Meta<WithMockedDate<typeof CalendarDateField>>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantStates: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="Fully booked days and past days (mocked today: 2023-05-01)" variantType="other">
      <Variant label="fullyBookedDates 3-6 May and 16 May (disabled with marker)">
        <div>
          <CalendarDateField
            {...args}
            calendarDates={{ ...calendarDates, selectedDates: [] }}
            fullyBookedDates={fullyBookedDates}
          />
        </div>
      </Variant>
      <Variant label="removeDaysInThePast false (opens on April with the past days kept)">
        <div>
          <CalendarDateField
            {...args}
            calendarDates={{ ...calendarDates, selectedDates: [] }}
            removeDaysInThePast={false}
          />
        </div>
      </Variant>
    </ShowcaseLayout>
  ),
};

const onChangeDateSpy = fn();

export const TestSelectDate: Story = {
  args: {
    fullyBookedDates,
    onChangeDate: onChangeDateSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeDateSpy.mockClear();
    const canvas = within(canvasElement);

    await userEvent.click(canvas.getByRole("button", { name: "onsdag 10 maj" }));
    await expect(onChangeDateSpy).toHaveBeenCalledTimes(1);
    const selected: Date = onChangeDateSpy.mock.calls[0][0];
    await expect([selected.getFullYear(), selected.getMonth(), selected.getDate()]).toEqual([2023, 4, 10]);

    // A fully booked day is disabled, so clicking it must not report a change.
    const fullyBooked = canvas.getByRole("button", { name: "onsdag 3 maj, Fullbokat" });
    await expect(fullyBooked).toBeDisabled();
    await userEvent.click(fullyBooked);
    await expect(onChangeDateSpy).toHaveBeenCalledTimes(1);

    // The selected marker animates in with framer-motion.
    await waitFor(() => expect(canvas.getByRole("button", { name: "onsdag 10 maj, Valt datum" })).toBeVisible());
  },
};
